const normalizeCareerKey = (value = "") =>
  String(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

const dedupe = (values) => {
  const seen = new Set();
  return values.filter((value) => {
    const key = String(value || "").trim().toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

const buildFallbackSalaryBands = (salaryText = "") => {
  const match = String(salaryText).match(/(\d+(?:\.\d+)?)\s*L?\s*[-–]\s*(\d+(?:\.\d+)?)\s*L/i);
  if (!match) {
    return [
      { label: "Entry Level", range: "INR 4-7 LPA", experience: "0-2 years" },
      { label: "Mid Level", range: "INR 7-12 LPA", experience: "3-7 years" },
      { label: "Senior Level", range: "INR 12-22 LPA", experience: "8+ years" },
    ];
  }

  const low = Number(match[1]);
  const high = Number(match[2]);
  const mid = Math.max(low + 1, Math.round((low + high) / 2));
  const seniorHigh = high + Math.max(4, Math.round((high - low) * 0.8));

  const fmt = (n) => (Number.isInteger(n) ? `${n}` : `${n}`);

  return [
    {
      label: "Entry Level",
      range: `INR ${fmt(low)}-${fmt(mid)} LPA`,
      experience: "0-2 years",
    },
    {
      label: "Mid Level",
      range: `INR ${fmt(mid)}-${fmt(high)} LPA`,
      experience: "3-7 years",
    },
    {
      label: "Senior Level",
      range: `INR ${fmt(high)}-${fmt(seniorHigh)} LPA`,
      experience: "8+ years",
    },
  ];
};

const buildFallbackResponsibilities = (title = "career") => [
  `Analyze problems and opportunities relevant to a ${title} role.`,
  "Collaborate with teams and stakeholders to move work forward.",
  "Use core tools, workflows, and domain knowledge to deliver outcomes.",
  "Present insights, progress, or recommendations clearly.",
  "Keep improving your methods through practice and feedback.",
];

export const buildCareerDetailPath = (careerOrTitle) => {
  const title =
    typeof careerOrTitle === "string" ? careerOrTitle : careerOrTitle?.title || "";
  return title ? `/careerdetail?career=${encodeURIComponent(title)}` : "/careerdetail";
};

export const getCareerDetailContent = (career = null) => {
  const title = career?.title || "Career Match";
  const key = normalizeCareerKey(title);
  const detail = CAREER_DETAIL_CONTENT[key] || {};
  const salaryText = detail.salaryRange || career?.salaryRange || "";

  // Required skills come ONLY from the curated detail entry, never from the
  // career matcher's aptitude / intelligence tags (which were leaking into the
  // UI as "skills" before this rewrite). Falls back to a sensible default
  // when a career is missing from the table.
  const resolvedSkills = dedupe(
    (detail.requiredSkills || []).slice(0)
  );

  const score =
    career?.score != null
      ? Number(career.score)
      : career?.matchPercent != null
        ? Number(career.matchPercent)
        : null;

  return {
    title,
    matchPercent: career?.matchPercent ?? Math.round(score ?? 82),
    score: score != null ? Math.round(score * 10) / 10 : null,
    category: career?.category || "",
    matchReasons: career?.matchReasons || null,
    breakdown: career?.breakdown || null,
    hollandCodes: Array.isArray(career?.hollandCodes) ? career.hollandCodes : [],
    intelligenceTypes: Array.isArray(career?.intelligenceTypes)
      ? career.intelligenceTypes
      : [],
    aptitudeStrengths: Array.isArray(career?.aptitudeStrengths)
      ? career.aptitudeStrengths
      : [],
    eqCompetencies: Array.isArray(career?.eqCompetencies)
      ? career.eqCompetencies
      : [],
    description:
      career?.description ||
      detail.overview ||
      `Explore what it takes to grow in ${title} and how it aligns with your profile.`,
    overview:
      detail.overview ||
      career?.description ||
      `This pathway blends the strengths and interests commonly associated with ${title}.`,
    salaryText,
    salaryBands: buildFallbackSalaryBands(salaryText),
    responsibilities:
      detail.keyResponsibilities ||
      detail.responsibilities ||
      buildFallbackResponsibilities(title.toLowerCase()),
    education: detail.education || DEFAULT_EDUCATION,
    outlook: detail.outlook || DEFAULT_OUTLOOK,
    companies: detail.companies || DEFAULT_COMPANIES,
    workEnvironment: detail.workEnvironment || "",
    guidancePoints: detail.guidancePoints || DEFAULT_GUIDANCE_POINTS,
    skills: resolvedSkills.length ? resolvedSkills : DEFAULT_SKILLS,
  };
};

export const matchCareerByTitle = (careers = [], title = "") => {
  const requestedKey = normalizeCareerKey(title);
  if (!requestedKey) return null;
  return careers.find((career) => normalizeCareerKey(career?.title) === requestedKey) || null;
};
